CREATE TABLE pricebook(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),code TEXT NOT NULL,description TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('labour','material','other')),unit_cents INTEGER NOT NULL CHECK(unit_cents>=0),active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,UNIQUE(company_id,code));
CREATE TRIGGER jobs_branch_insert BEFORE INSERT ON jobs WHEN NEW.branch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM branches WHERE company_id=NEW.company_id AND id=NEW.branch_id) BEGIN SELECT RAISE(ABORT,'Invalid job branch'); END;
CREATE TRIGGER jobs_branch_update BEFORE UPDATE OF branch_id ON jobs WHEN NOT EXISTS(SELECT 1 FROM branches WHERE company_id=NEW.company_id AND id=NEW.branch_id) BEGIN SELECT RAISE(ABORT,'Invalid job branch'); END;
CREATE TRIGGER customer_branch_update BEFORE UPDATE OF branch_id ON customers WHEN NOT EXISTS(SELECT 1 FROM branches WHERE company_id=NEW.company_id AND id=NEW.branch_id) BEGIN SELECT RAISE(ABORT,'Invalid customer branch'); END;
CREATE TRIGGER job_area_update BEFORE UPDATE OF service_area_id ON jobs WHEN NEW.service_area_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_areas WHERE company_id=NEW.company_id AND id=NEW.service_area_id AND branch_id=NEW.branch_id AND active=1) BEGIN SELECT RAISE(ABORT,'Invalid job service area'); END;
